const app=document.querySelector('#app');
let backendOnline=false;
const S={logged:localStorage.getItem('sprayscope-email-auth')==='1'||sessionStorage.getItem('sprayscope-email-auth')==='1',userName:localStorage.getItem('sprayscope-email')||sessionStorage.getItem('sprayscope-email')||'Analyst',page:'Overview',events:[],raw:[],columns:[],map:{},datasetName:'No dataset loaded',source:'demo',isMock:false,incidents:[],selected:null,entity:null,status:'Idle',range:60,search:'',filter:{type:'All',severity:'All'},zoom:1,pan:{x:0,y:0},activityFilter:{country:'All',device:'All',result:'All',status:'All',minRisk:0,type:'All',severity:'All'},graphIncidentId:null,replay:null};
const nav=[['Overview','◫'],['User VPN Portal','⇥'],['Dataset','▤'],['Analyze Logs','⌁'],['Incidents','⚑'],['Activity Timeline','◷'],['Attack Graph','◎'],['Metrics','％'],['Reports','⇩'],['Settings','⚙']];
let publicPortal=new URLSearchParams(location.search).get('portal')==='1';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=x=>x?new Date(x).toLocaleString():'—';
const formatIP=x=>esc(x||'Unknown');
const typeBadge=()=>`<span class="tag ${S.source==='synthetic'?'synthetic':S.source==='real'?'real':'demo'}">${S.source==='synthetic'?'SYNTHETIC LABELLED DATA':S.source==='real'?'REAL DATA':'DEMO DATA'}</span>`;
function toast(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),2600);}
let authMode='signin';
function login(){
 const signup=authMode==='signup';
 app.innerHTML=`<div class="login"><div class="login-art"><div class="brand">CYBER<b>NOVA</b></div><div class="network"><svg viewBox="0 0 500 420" fill="none"><g stroke="#55d6e8" stroke-opacity=".28"><path d="M30 280 130 190 230 230 320 90 460 150M130 190 170 60 320 90M230 230 280 360 460 150M30 280 150 350 280 360M320 90 440 30"/><path d="M130 190 280 360M230 230 440 30" stroke-dasharray="3 8"/></g><g fill="#55d6e8"><circle cx="30" cy="280" r="4"/><circle cx="130" cy="190" r="6"/><circle cx="230" cy="230" r="4"/><circle cx="320" cy="90" r="7"/><circle cx="460" cy="150" r="4"/><circle cx="170" cy="60" r="3"/><circle cx="280" cy="360" r="5"/><circle cx="150" cy="350" r="3"/><circle cx="440" cy="30" r="4"/></g><circle cx="320" cy="90" r="26" stroke="#55d6e8" stroke-opacity=".4"/><circle cx="320" cy="90" r="42" stroke="#55d6e8" stroke-opacity=".2"/></svg></div><div class="hero"><div class="eyebrow">VPN THREAT DETECTION & INVESTIGATION</div><h1>Someone’s<br><span>spraying</span><br>the VPN.</h1><p>Turn authentication noise into a clear investigation trail. Detect brute force, password spraying and impossible travel across your login events.</p></div><div class="tiny muted">CYBERNOVA · SECURITY OPERATIONS</div></div><div class="login-panel"><div class="login-card"><div class="eyebrow">SECURE ACCESS</div><h2>${signup?'Create your account':'Welcome to SprayScope'}</h2><p>${signup?'Register once, then sign in with the same credentials.':'Sign in with your registered SprayScope account.'}</p><form id="loginForm"><label>Email<input class="field" type="email" name="email" autocomplete="email" placeholder="analyst@cybernova.test" required></label><label>Password<input class="field" type="password" name="password" autocomplete="${signup?'new-password':'current-password'}" placeholder="${signup?'At least 8 characters':'Your password'}" minlength="${signup?8:1}" required></label>${signup?'<label>Confirm password<input class="field" type="password" name="confirmPassword" autocomplete="new-password" minlength="8" placeholder="Re-enter your password" required></label>':'<label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="remember" checked> Remember me</label>'}<button class="btn">${signup?'Sign Up':'Sign In'}</button></form><p class="tiny" style="text-align:center;margin:14px 0">${signup?'Already registered?':'New to SprayScope?'} <button type="button" id="authToggle" class="btn ghost sm">${signup?'Sign in':'Sign up'}</button></p><div class="or">OR</div><button class="btn secondary" id="msLogin">Continue with Microsoft</button><p class="tiny muted" style="margin-top:18px">${signup?'Prototype account details are stored in this browser only.':'Use the email and password you registered with.'}</p><a class="portal-entry" href="?portal=1">Open the VPN user sign-in page <span>↗</span></a></div></div></div>`;
 document.querySelector('#authToggle').onclick=()=>{authMode=signup?'signin':'signup';login();};
 document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();const email=document.querySelector('[name="email"]').value.trim().toLowerCase(),password=document.querySelector('[name="password"]').value;try{if(signup){const confirm=document.querySelector('[name="confirmPassword"]').value;if(password.length<8)throw Error('Use at least 8 characters for your password.');if(password!==confirm)throw Error('The passwords do not match.');const users=readUsers();if(users[email])throw Error('An account with this email already exists. Sign in instead.');const salt=randomSalt(),hash=await hashPassword(password,salt);users[email]={salt,hash};localStorage.setItem('sprayscope-users',JSON.stringify(users));S.userName=email;authSuccess(email,true);}else{const user=readUsers()[email];if(!user)throw Error('No account found for this email. Sign up first.');const hash=await hashPassword(password,user.salt);if(hash!==user.hash)throw Error('Incorrect email or password.');S.userName=email;authSuccess(email,document.querySelector('[name="remember"]').checked);}}catch(err){toast(err.message||'Sign-in failed.');}};
 document.querySelector('#msLogin').onclick=()=>signInMicrosoft().catch(e=>toast(`Microsoft sign-in failed: ${e.message}`));
}
function readUsers(){try{return JSON.parse(localStorage.getItem('sprayscope-users')||'{}');}catch{return {};}}
function randomSalt(){const bytes=crypto.getRandomValues(new Uint8Array(16));return btoa(String.fromCharCode(...bytes));}
function hashPassword(password,salt){const saltBytes=Uint8Array.from(atob(salt),c=>c.charCodeAt(0));return crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']).then(key=>crypto.subtle.deriveBits({name:'PBKDF2',salt:saltBytes,iterations:150000,hash:'SHA-256'},key,256)).then(bits=>btoa(String.fromCharCode(...new Uint8Array(bits))));}
function authSuccess(email,remember){sessionStorage.setItem('sprayscope-email',email);if(remember){localStorage.setItem('sprayscope-email-auth','1');localStorage.setItem('sprayscope-email',email);}else{localStorage.removeItem('sprayscope-email-auth');sessionStorage.setItem('sprayscope-email-auth','1');}S.logged=true;render();}let microsoftClient=null;
async function loadMsal(){if(window.msal?.PublicClientApplication)return;await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://alcdn.msauth.net/browser/2.35.0/js/msal-browser.min.js';script.integrity='sha384-PARf28kmic36Ve+O3DnUerRXFtOQ7ZDqRDGpLcbljly5/N39T2OV3kt3QsWOKeAX';script.crossOrigin='anonymous';script.onload=resolve;script.onerror=()=>reject(Error('Microsoft MSAL library could not be downloaded. Check internet access.'));document.head.append(script);});if(!window.msal?.PublicClientApplication)throw Error('Microsoft MSAL library did not initialize.');}
async function signInMicrosoft(){if(!MICROSOFT_CLIENT_ID){showModal('Microsoft sign-in setup required','This button uses Microsoft Entra ID authentication and will not sign you in with a fake session. Add your Entra Application (client) ID in frontend/src/authConfig.js, then register http://localhost:4173/ as a Single-page application redirect URI. Send me the client ID and account scope to finish configuring it.');return;}await loadMsal();microsoftClient??=new window.msal.PublicClientApplication({auth:{clientId:MICROSOFT_CLIENT_ID,authority:MICROSOFT_AUTHORITY,redirectUri:`${location.origin}/`},cache:{cacheLocation:'sessionStorage'}});await microsoftClient.loginRedirect({scopes:['openid','profile','email']});}
function shell(){app.innerHTML=`<div class="layout"><aside class="sidebar"><div class="side-brand">SprayScope<span>CYBERNOVA SECURITY</span></div><nav class="nav">${nav.map(([n,i])=>`<button data-page="${n}" class="${S.page===n?'active':''}"><span class="ico">${i}</span><span class="label">${n}</span></button>`).join('')}</nav><div class="side-bottom"><div class="engine">Detection Engine: ONLINE</div><div class="footlabel tiny muted" style="margin:10px 0 0">Rules run locally on loaded events</div></div></aside><main class="main"><header class="topbar"><div class="search"><input id="search" class="field" placeholder="Search incidents, users, IPs…" value="${esc(S.search)}"></div><div class="top-right"><span class="tag ${S.status==='Complete'?'good':'demo'} hide-mobile">${S.status==='Complete'?'ANALYSIS COMPLETE':'ANALYSIS '+S.status.toUpperCase()}</span><button id="notifications" title="Notifications">♧</button><div class="user-chip"><div class="avatar">A</div><span class="who">Analyst</span></div><button id="logout">Log out</button></div></header><section class="content" id="content"></section></main></div>`;
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{S.page=b.dataset.page;S.selected=null;render();});document.querySelector('#logout').onclick=()=>{localStorage.removeItem('sprayscope-auth');S.logged=false;login();};document.querySelector('#search').oninput=e=>{S.search=e.target.value;if(S.page==='Incidents')renderPage();};document.querySelector('#notifications').onclick=()=>toast(S.incidents.length?`${S.incidents.length} incidents in current analysis`:'No new notifications');renderPage();}
function head(title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">CYBERNOVA / SECURITY OPERATIONS</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function cardTitle(title,sub=''){return `<div class="card-title"><div><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}</div></div>`;}
const count=(fn)=>S.events.filter(fn).length;
function stat(label,val,ico,note='From current dataset'){return `<div class="stat"><div class="stat-head">${label}<span class="stat-icon">${ico}</span></div><strong>${val}</strong><small>${note}</small></div>`;}
function sev(s){return `<span class="severity ${s?.toLowerCase()}">${esc(s||'—')}</span>`;}
function incidentRows(rows){return rows.map(i=>`<tr class="clickable" data-incident="${i.id}"><td class="mono">${i.id}</td><td>${i.type}</td><td class="mono">${formatIP(i.source_ip)}</td><td>${i.users.length===1?esc(i.users[0]):`${i.users.length} users`}</td><td>${time(i.first_seen)}</td><td>${i.attempts}</td><td><b>${i.risk}</b></td><td>${sev(i.severity)}</td><td class="mono">${i.mitre}</td><td>${i.status}</td></tr>`).join('');}
function table(rows){return `<div class="table-wrap"><table><thead><tr><th>Incident ID</th><th>Attack type</th><th>Source IP</th><th>User(s)</th><th>First seen</th><th>Attempts</th><th>Risk</th><th>Severity</th><th>MITRE</th><th>Status</th></tr></thead><tbody>${rows||''}</tbody></table></div>`;}
function chartSVG(){const ev=S.events.filter(e=>Date.parse(e.timestamp)>=Date.now()-S.range*60000),bins=Array.from({length:24},()=>({ok:0,fail:0,attack:0}));const min=Math.min(...S.events.map(e=>Date.parse(e.timestamp))),max=Math.max(...S.events.map(e=>Date.parse(e.timestamp))),span=Math.max(1,max-min),predicted=new Set(S.incidents.flatMap(i=>i.events));ev.forEach(e=>{const i=Math.min(23,Math.floor((Date.parse(e.timestamp)-min)/span*24));bins[i][e.result==='success'?'ok':'fail']++;if(predicted.has(e))bins[i].attack++;});const mx=Math.max(1,...bins.map(b=>Math.max(b.ok,b.fail,b.attack)));const pts=k=>bins.map((b,i)=>`${15+i*30},${200-b[k]/mx*155}`).join(' ');return `<svg viewBox="0 0 730 225" preserveAspectRatio="none"><g stroke="#21364c" stroke-width="1"><path d="M15 45H715M15 95H715M15 145H715M15 195H715"/></g><g fill="#71869d" font-size="9"><text x="15" y="217">${new Date(min||Date.now()).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</text><text x="660" y="217">${new Date(max||Date.now()).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</text></g><polyline points="${pts('ok')}" fill="none" stroke="#52d6a0" stroke-width="2"/><polyline points="${pts('fail')}" fill="none" stroke="#5797ff" stroke-width="2"/><polyline points="${pts('attack')}" fill="none" stroke="#ff7184" stroke-width="2" stroke-dasharray="4 4"/>${S.incidents.slice(0,8).map((i,n)=>`<circle cx="${80+n*75}" cy="28" r="4" fill="#ff7184" style="cursor:pointer" data-incident="${i.id}"/>`).join('')}</svg>`;}
function activityCard(){return `<div class="card">${cardTitle('Authentication activity','Events over time · detected attacks marked in red')}<div class="row" style="margin-bottom:7px"><div class="legend"><span><i class="dot" style="background:#52d6a0"></i>Successful</span><span><i class="dot" style="background:#5797ff"></i>Failed</span><span><i class="dot" style="background:#ff7184"></i>Detected attacks</span></div><select id="range" class="field" style="width:auto;padding:6px;font-size:10px">${[5,10,30,60,1440].map(x=>`<option value="${x}" ${S.range===x?'selected':''}>${x<60?x+' min':x===60?'1 hour':'24 hours'}</option>`).join('')}</select></div><div class="chart">${chartSVG()}</div></div>`;}
function overview(){const high=S.incidents.filter(i=>i.risk>=70).length,atrisk=new Set(S.incidents.flatMap(i=>i.users)).size;return `${head('Security Operations Overview','Authentication threat summary · '+esc(S.datasetName),`${typeBadge()}<button class="btn secondary sm" data-action="demoSpray">Run Password Spray Demo</button>`)}<div class="grid stats">${stat('Total logins',S.events.length,'↗')}${stat('Failed logins',count(e=>e.result==='failure'),'×')}${stat('Successful logins',count(e=>e.result==='success'),'✓')}${stat('Unique users',new Set(S.events.map(e=>e.username)).size,'♙')}${stat('Unique IPs',new Set(S.events.map(e=>e.source_ip)).size,'⌖')}${stat('Detected incidents',S.incidents.length,'⚑')}${stat('High / critical',high,'!')}${stat('Users at risk',atrisk,'◉')}</div><div class="grid cols"><div>${activityCard()}<div class="card">${cardTitle('Recent incidents','Highest risk detections from the current run')}${table(incidentRows(S.incidents.slice(0,5)))}</div></div><div><div class="card">${cardTitle('Detection engine','Rules run against normalized authentication events')}<div class="engine" style="margin:15px 0">ONLINE</div><div class="row tiny"><span>Dataset status</span>${typeBadge()}</div><hr style="border-color:var(--line);margin:15px 0"><div class="row tiny"><span>Last analysis</span><span class="muted">${S.status==='Complete'?'Completed':'Not run'}</span></div><button class="btn" style="width:100%;margin-top:18px" data-page="Dataset">Load or upload logs</button></div><div class="card">${cardTitle('Techniques observed')}<div class="grid" style="gap:10px"><div class="row tiny"><span>Brute force</span><span class="mono">T1110.001</span></div><div class="row tiny"><span>Password spray</span><span class="mono">T1110.003</span></div><div class="row tiny"><span>Valid accounts</span><span class="mono">T1078</span></div></div></div></div></div>`;}
function dataset(){return `${head('Authentication Log Dataset','Load an authentication log file or start with a small local demonstration sample.',typeBadge())}<div class="grid two"><div class="card">${cardTitle('A · Upload dataset','CSV, JSON, or line-delimited JSON · processed in this browser')}<div id="drop" class="upload"><div style="font-size:24px;color:var(--cyan)">⇧</div><h3>Drop your authentication logs here</h3><p>or choose a file from your device · CSV / JSON</p><label class="btn secondary" style="display:inline-flex;cursor:pointer">Choose file<input id="file" type="file" accept=".csv,.json,.txt,.log, text/csv,application/json"></label><p class="tiny">Text logs need structured CSV or JSON fields for mapping.</p></div><p class="tiny muted" style="margin-top:13px">CSV headers are mapped after preview. Large files may take longer to analyze.</p><a class="btn ghost sm" style="display:inline-block" href="dataset/demo-authentication.csv" download>↓ Download demo CSV</a></div><div class="card">${cardTitle('B · Use demo dataset','A local representative sample for trying the detection workflow')}<div class="upload" style="padding:23px"><div class="eyebrow">LOCAL SAMPLE · NOT DOWNLOADED FROM LOGHUB</div><h3>Try SprayScope with sample authentication events</h3><p>Includes illustrative failed and successful VPN logins for previewing rules. No ground truth metrics are reported for this sample.</p><button class="btn" data-action="loadDemo">Load Demo Dataset</button><p class="tiny muted">Or upload the ready-to-use file: <a href="dataset/demo-authentication.csv" download>demo-authentication.csv</a></p></div><div style="margin-top:18px"><a href="https://github.com/logpai/loghub" target="_blank" rel="noreferrer" class="tiny">LogHub public dataset source ↗</a><p class="tiny muted">LogHub contains system log datasets; this prototype does not download or claim to include the full LogHub corpus. Upload an appropriate authentication log export above.</p></div></div></div>${S.raw.length?`<div class="card">${cardTitle('Dataset preview',`${esc(S.datasetName)} · ${S.raw.length} rows · ${S.columns.length} columns`)}<div class="table-wrap"><table><thead><tr>${S.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${S.raw.slice(0,8).map(row=>`<tr>${S.columns.map(c=>`<td>${esc(row[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="tiny muted">Showing up to 8 rows. Detected ${new Set(S.events.map(e=>e.username)).size} users, ${new Set(S.events.map(e=>e.source_ip)).size} IPs; ${count(e=>e.result==='success')} successes and ${count(e=>e.result==='failure')} failures after mapping.</p><button class="btn" data-page="Analyze Logs">Continue to column mapping</button></div>`:''}`;}
function mapping(){if(!S.raw.length)return `${head('Analyze Logs','Load a dataset to map authentication fields.') }<div class="card empty">No dataset loaded yet. <button class="btn sm" data-page="Dataset">Open Dataset</button></div>`;const required=['timestamp','username','source_ip','result'];return `${head('Column Mapping','Match the source columns to normalized authentication fields.',typeBadge())}<div class="card">${cardTitle('Map source fields','Required fields are timestamp, username, source IP, and result.')}<div>${Object.entries(S.map).map(([k,v])=>`<div class="mapping-row"><span>${esc(k.replace('_',' '))} ${required.includes(k)?'<b style="color:var(--cyan)">*</b>':''}</span><span class="muted">→</span><select data-map="${k}"><option value="">Select source column…</option>${S.columns.map(c=>`<option value="${esc(c)}" ${c===v?'selected':''}>${esc(c)}</option>`).join('')}</select></div>`).join('')}</div><div class="checks">${required.map(k=>`<span class="check ${S.map[k]?'':'miss'}">${S.map[k]?'✓':'!'} ${k.replace('_',' ')} ${S.map[k]?'found':'required'}</span>`).join('')}</div><div class="row"><span class="tiny muted">${S.raw.length} records loaded · unrecognized results remain unknown</span><button class="btn" data-action="analyze" ${required.some(k=>!S.map[k])?'disabled':''}>Confirm & Analyze</button></div></div><div class="card">${cardTitle('Data preview','First 10 source rows')}<div class="table-wrap"><table><thead><tr>${S.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${S.raw.slice(0,10).map(r=>`<tr>${S.columns.map(c=>`<td>${esc(r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;}
const steps=['Loading logs','Parsing events','Normalizing timestamps','Normalizing usernames','Normalizing IP addresses','Identifying success / failure','Building time windows','Detecting attack patterns','Calculating severity','Mapping MITRE ATT&CK','Calculating evaluation metrics'];
function analyzeView(){return `${head('Analyze Logs','Normalize the current dataset and run the detection rules.',typeBadge())}<div class="card">${cardTitle('Analysis pipeline','Browser-side processing · no events sent to a server')}<div id="pipeline" class="pipeline">${steps.map((s,i)=>`<div class="pipe-step" data-step="${i}">${String(i+1).padStart(2,'0')} · ${s}</div>`).join('')}</div><div class="progress"><i id="progress" style="width:0%"></i></div><p id="analysisMessage" class="tiny muted">Ready when you are.</p><button class="btn" data-action="analyze" ${S.events.length?'':'disabled'}>Run Detection</button></div><div class="card">${cardTitle('Detection logic','Explainable rules applied to your mapped authentication events')}<div class="grid three tiny"><div><b>Brute force</b><p class="muted">≥10 failed attempts for one user within 5 minutes · T1110.001</p></div><div><b>Password spray</b><p class="muted">≥10 distinct users from one source within 10 minutes; ≤5 attempts per user on average · T1110.003</p></div><div><b>Impossible travel</b><p class="muted">Two successful logins >500 km apart at >900 km/h using country centroids where country codes are available · T1078</p></div></div><p class="tiny muted">IP geolocation is not fabricated. Without known country codes, impossible travel is not evaluated for those events.</p></div>`;}
function incidentList(){let list=[...S.incidents];if(S.filter.type!=='All')list=list.filter(i=>i.type===S.filter.type);if(S.filter.severity!=='All')list=list.filter(i=>i.severity===S.filter.severity);if(S.search)list=list.filter(i=>`${i.id} ${i.type} ${i.source_ip} ${i.users.join(' ')}`.toLowerCase().includes(S.search.toLowerCase()));return `${head('Incidents','Investigate detection results from the current analysis.',typeBadge())}<div class="card"><div class="filters"><select id="typeFilter"><option>All</option>${['Brute Force','Password Spray','Impossible Travel'].map(x=>`<option ${S.filter.type===x?'selected':''}>${x}</option>`).join('')}</select><select id="sevFilter"><option>All</option>${['CRITICAL','HIGH','MEDIUM','LOW'].map(x=>`<option ${S.filter.severity===x?'selected':''}>${x}</option>`).join('')}</select><select id="sort"><option value="risk">Highest risk</option><option value="new">Newest</option><option value="users">Most users affected</option></select></div>${table(incidentRows(list))}${list.length?'':`<div class="empty">No incidents match the filters. Load a dataset and run detection to populate this table.</div>`}</div>`;}
function investigation(i){return `${head('Incident Investigation',`${i.id} · ${i.type} · ${time(i.first_seen)}`,`<button class="btn secondary sm" data-action="backIncidents">← Incidents</button>`)}<div class="grid cols"><div><div class="card"><div class="incident-hero">${sev(i.severity)}<h2>${i.type}</h2><span class="mono">${i.id} · ${i.mitre}</span></div><p style="font-size:13px;line-height:1.7;margin-top:20px">${esc(i.reason)}</p><p class="tiny muted">Investigate the source IP and affected accounts. Review successful activity and validate with identity provider records.</p><div class="actions"><button class="btn sm" data-action="investigated" data-id="${i.id}">Mark Investigated</button><button class="btn secondary sm" data-action="evidence" data-id="${i.id}">Export Evidence</button><button class="btn secondary sm" data-action="kql" data-id="${i.id}">Generate KQL</button><button class="btn secondary sm" data-action="sendAlert" data-id="${i.id}">Send Alert</button></div><p class="tiny muted">“Send Alert” creates a local alert preview; no external service is connected.</p></div><div class="card">${cardTitle('Why detected')}<div class="grid two tiny"><div>Failed login volume<br><b>${i.events.filter(e=>e.result==='failure').length}</b></div><div>Users affected<br><b>${i.users.length}</b></div><div>Time window<br><b>${Math.max(0,Math.round((Date.parse(i.last_seen)-Date.parse(i.first_seen))/60000))} min</b></div><div>Attempts per user<br><b>${(i.attempts/Math.max(1,i.users.length)).toFixed(1)}</b></div></div><p class="tiny muted">Location context: ${i.type==='Impossible Travel'?'Country codes supplied in source log; comparison uses country centroids.':'No geolocation inference used for this detection.'}</p></div></div><div><div class="card">${cardTitle('Incident facts')}<div class="grid" style="gap:13px;font-size:11px"><div class="row"><span class="muted">Risk score</span><b style="color:var(--red)">${i.risk} / 100</b></div><div class="row"><span class="muted">Severity</span>${sev(i.severity)}</div><div class="row"><span class="muted">Source IP</span><span class="mono">${formatIP(i.source_ip)}</span></div><div class="row"><span class="muted">First / last seen</span><span>${time(i.first_seen)}<br>${time(i.last_seen)}</span></div><div class="row"><span class="muted">MITRE ATT&CK</span><button class="btn ghost sm" data-action="mitre" data-id="${i.id}">${i.mitre} ↗</button></div></div></div><div class="card">${cardTitle('Affected users')}<div class="tiny">${i.users.map(u=>`<div class="row" style="padding:7px 0;border-bottom:1px solid var(--line)"><span>${esc(u)}</span><span class="muted">${i.events.filter(e=>e.username===u).length} events</span></div>`).join('')}</div></div></div></div><div class="card">${cardTitle('Evidence events',`${i.events.length} events associated with this detection`)}<div class="table-wrap evidence-list"><table><thead><tr><th>Timestamp</th><th>Username</th><th>Source IP</th><th>Result</th><th>Country</th><th>Device</th></tr></thead><tbody>${i.events.map(e=>`<tr><td>${time(e.timestamp)}</td><td>${esc(e.username)}</td><td class="mono">${formatIP(e.source_ip)}</td><td>${esc(e.result)}</td><td>${esc(e.country||'—')}</td><td>${esc(e.device||'—')}</td></tr>`).join('')}</tbody></table></div></div>`;}
function timeline(){const bins=Array.from({length:48},()=>({ok:0,fail:0,attack:false}));if(S.events.length){const min=Math.min(...S.events.map(e=>Date.parse(e.timestamp))),span=Math.max(1,Math.max(...S.events.map(e=>Date.parse(e.timestamp)))-min);for(const e of S.events){const i=Math.min(47,Math.floor((Date.parse(e.timestamp)-min)/span*48));if(e.result==='success')bins[i].ok++;else bins[i].fail++;}for(const inc of S.incidents){const i=Math.min(47,Math.floor((Date.parse(inc.first_seen)-min)/span*48));if(i>=0)bins[i].attack=true;}}const max=Math.max(1,...bins.map(b=>b.ok+b.fail));return `${head('Activity Timeline','Distribution of events across the loaded analysis window.',typeBadge())}<div class="card">${cardTitle('Events per interval','Each bar represents a normalized time bucket')}<div class="timeline">${bins.map((b,i)=>`<i class="${b.attack?'attack':''}" style="height:${Math.max(2,(b.ok+b.fail)/max*130)}px" data-tip="Bucket ${i+1}: ${b.ok+b.fail} events${b.attack?' · attack detected':''}"></i>`).join('')}</div><div class="legend"><span><i class="dot" style="background:var(--cyan)"></i>Authentication volume</span><span><i class="dot" style="background:var(--red)"></i>Attack detected</span></div></div>${activityCard()}`;}
function graph(){const incidents=S.incidents;if(!incidents.length)return `${head('Attack Graph','Source-to-user relationships in detected incidents.') }<div class="card empty">Run detection to build the attack graph.</div>`;const inc=S.selected&&incidents.find(x=>x.id===S.selected)||incidents[0],users=inc.users.slice(0,18),cx=450,cy=205,r=140,points=users.map((u,i)=>({u,x:cx+Math.cos(2*Math.PI*i/users.length)*r,y:cy+Math.sin(2*Math.PI*i/users.length)*r}));return `${head('Attack Graph','Select a user or source node to inspect the incident relationship.',typeBadge())}<div class="grid cols"><div class="card"><div class="filters"><select id="graphSelect">${incidents.map(x=>`<option value="${x.id}" ${inc.id===x.id?'selected':''}>${x.id} · ${x.type}</option>`).join('')}</select><button class="btn secondary sm" data-action="zoomIn">＋</button><button class="btn secondary sm" data-action="zoomOut">−</button><button class="btn ghost sm" data-action="resetZoom">Reset</button></div><div class="graph-area" id="graphArea"><svg viewBox="0 0 900 410"><g transform="translate(${S.pan.x} ${S.pan.y}) scale(${S.zoom})">${points.map(p=>`<line x1="${cx}" y1="${cy}" x2="${p.x}" y2="${p.y}" stroke="#42627d" stroke-width="1.5"/>`).join('')}<g class="node" data-node="${esc(inc.source_ip)}"><circle cx="${cx}" cy="${cy}" r="35" fill="#18364f" stroke="#55d6e8" stroke-width="2"/><text x="${cx}" y="${cy-3}" fill="#e8f0fa" text-anchor="middle" font-size="11">SOURCE</text><text x="${cx}" y="${cy+12}" fill="#55d6e8" text-anchor="middle" font-size="10">${esc(inc.source_ip)}</text></g>${points.map(p=>`<g class="node" data-node="${esc(p.u)}"><circle cx="${p.x}" cy="${p.y}" r="18" fill="#182941" stroke="#5797ff"/><text x="${p.x}" y="${p.y+32}" fill="#cbd9e8" text-anchor="middle" font-size="10">${esc(p.u.length>20?p.u.slice(0,18)+'…':p.u)}</text></g>`).join('')}</g></svg></div></div><div class="card" id="nodeInfo">${cardTitle('Selected incident')}<h3>${inc.type}</h3><div class="grid" style="gap:10px;font-size:11px"><div class="row"><span class="muted">Source IP</span><span class="mono">${esc(inc.source_ip)}</span></div><div class="row"><span class="muted">Users targeted</span><b>${inc.users.length}</b></div><div class="row"><span class="muted">Failures</span><b>${inc.events.filter(e=>e.result==='failure').length}</b></div><div class="row"><span class="muted">Successes</span><b>${inc.events.filter(e=>e.result==='success').length}</b></div><div class="row"><span class="muted">Risk</span><b>${inc.risk}/100 · ${inc.severity}</b></div></div><p class="tiny muted">Graph shows source-to-user links from incident evidence. Country nodes appear only when country data is provided.</p></div></div>`;}
function metrics(){const labelled=S.events.some(e=>e.label);if(!labelled)return `${head('Detection Metrics','Evaluation requires ground truth labels attached to the loaded events.',typeBadge())}<div class="card"><div class="eyebrow">UNLABELED DATASET</div><h2 style="font-size:18px">Ground truth labels unavailable for this dataset.</h2><p class="muted" style="font-size:12px;line-height:1.7">Precision, recall, and alert-to-true-positive ratio are not reported for unlabeled data. Generate a synthetic labelled dataset to evaluate the detector using known outcomes.</p><button class="btn" data-page="Settings">Generate labelled test data</button></div>`;const m=calculateConfusionMatrix(S.events,S.incidents);return `${head('Detection Metrics','Evaluation calculated from event-level synthetic ground truth labels.',typeBadge())}<div class="grid stats">${stat('Precision',`${(m.precision*100).toFixed(1)}%`,'◎','TP / (TP + FP)')}${stat('Recall',`${(m.recall*100).toFixed(1)}%`,'↗','TP / (TP + FN)')}${stat('Alert-to-TP ratio',m.ratio===null?'—':m.ratio.toFixed(2),'⚑','Alert incidents / TP incidents')}${stat('Total alerts',m.totalAlerts,'!','Detected incidents')}</div><div class="grid two"><div class="card">${cardTitle('Confusion matrix','Event-level comparison of detector output with labels')}<div class="matrix"><div></div><div class="head">Predicted attack</div><div class="head">Predicted normal</div><div class="head">Actual attack</div><div><b>${m.tp}</b><br><span class="tiny muted">TP</span></div><div><b>${m.fn}</b><br><span class="tiny muted">FN</span></div><div class="head">Actual normal</div><div><b>${m.fp}</b><br><span class="tiny muted">FP</span></div><div><b>${m.tn}</b><br><span class="tiny muted">TN</span></div></div></div><div class="card">${cardTitle('Evaluation counts')}<div class="grid" style="gap:14px;font-size:12px">${[['True positives',m.tp],['False positives',m.fp],['False negatives',m.fn],['True negatives',m.tn]].map(([k,v])=>`<div class="row"><span class="muted">${k}</span><b>${v}</b></div>`).join('')}</div><p class="tiny muted" style="margin-top:20px">Counts are event-level: an event is predicted if it is included in at least one incident. Precision, recall, and matrix counts are event-level. Alert-to-TP ratio is total incidents divided by true-positive incidents.</p></div></div>`;}
function settings(){return `${head('Generate Test Dataset','Generate explicitly labelled synthetic authentication events for evaluation.') }<div class="grid two"><div class="card">${cardTitle('Synthetic event generator','Generated events are labelled normal or by injected attack type.')}<div class="grid two"><label>Scenario<select class="field" id="scenario"><option value="mix">Mixed scenarios</option><option value="normal">Normal login activity</option><option value="brute_force">Brute force</option><option value="password_spray">Password spray</option><option value="impossible_travel">Impossible travel</option></select></label><label>Number of users<input class="field" id="usersN" type="number" min="5" max="200" value="40"></label><label>Number of events<input class="field" id="eventsN" type="number" min="30" max="3000" value="300"></label><label>Attack intensity<input class="field" id="intensity" type="number" min="1" max="5" value="2"></label><label>Attack duration (minutes)<input class="field" id="duration" type="number" min="2" max="60" value="10"></label></div><button class="btn" style="margin-top:16px" data-action="generate">Generate Dataset</button></div><div class="card">${cardTitle('Built-in demos','Inject an attack pattern into the current data and immediately run the detector.')}<div class="grid" style="gap:11px"><button class="btn secondary" data-action="demoBrute">Run Brute Force Demo</button><button class="btn secondary" data-action="demoSpray">Run Password Spray Demo</button><button class="btn secondary" data-action="demoTravel">Run Impossible Travel Demo</button></div><p class="tiny muted" style="margin-top:15px">Demos are labelled synthetic events and will replace the current dataset.</p></div></div>${S.events.length?`<div class="card">${cardTitle('Current synthetic dataset',`${S.events.length} generated events`)}<p class="tiny">${S.events.filter(e=>e.label!=='normal').length} attack events · ${S.events.filter(e=>e.label==='normal').length} normal events</p><button class="btn secondary sm" data-action="analyze">Run Detection</button></div>`:''}`;}
function reports(){const m=S.events.some(e=>e.label)?calculateConfusionMatrix(S.events,S.incidents):null;return `${head('Reports','Export a summary of the current dataset and analysis.',typeBadge())}<div class="card">${cardTitle('Analysis report','Report values are calculated from the current loaded events.')}<div id="reportText" class="grid two tiny"><div><b>Dataset</b><p>${esc(S.datasetName)} · ${S.source==='real'?'Real data':S.source==='synthetic'?'Synthetic labelled data':'Demo data'}</p><b>Analysis period</b><p>${time(S.events[0]?.timestamp)} — ${time(S.events.at(-1)?.timestamp)}</p><b>Total events</b><p>${S.events.length}</p><b>Detection summary</b><p>${S.incidents.length} incidents · ${S.incidents.filter(i=>i.risk>=70).length} High/Critical</p></div><div><b>Attack types</b><p>${['Brute Force','Password Spray','Impossible Travel'].map(t=>`${t}: ${S.incidents.filter(i=>i.type===t).length}`).join('<br>')}</p><b>Precision</b><p>${m?`${(m.precision*100).toFixed(1)}%`:'Not available — dataset is unlabeled.'}</p><b>Recall</b><p>${m?`${(m.recall*100).toFixed(1)}%`:'Not available — dataset is unlabeled.'}</p><b>Alert-to-true-positive ratio</b><p>${m&&m.ratio!==null?m.ratio.toFixed(2):'Not available — dataset is unlabeled.'}</p></div></div><div class="actions"><button class="btn secondary" data-action="exportCSV">Download CSV</button><button class="btn secondary" data-action="exportJSON">Download JSON</button><button class="btn" data-action="exportReport">Export report</button></div></div><div class="card">${cardTitle('Incident summary')}${table(incidentRows(S.incidents))}</div>`;}
function liveStatus(){const i=[...S.incidents].sort((a,b)=>b.risk-a.risk)[0];return i?`<div class="threat-banner"><span class="threat-pulse"></span><div class="threat-banner-copy"><div class="eyebrow red-text">VPN THREAT DETECTED · ${i.severity}</div><b>${esc(i.type)} is active</b><p>${esc(i.reason)}</p><div class="threat-facts"><span>Confidence <b>${confidenceFor(i)}%</b></span><span>Affected users <b>${i.users.length}</b></span><span>Source IPs <b>${new Set(i.events.map(e=>e.source_ip)).size}</b></span><span>First seen <b>${new Date(i.first_seen).toLocaleTimeString()}</b></span><span>Last seen <b>${new Date(i.last_seen).toLocaleTimeString()}</b></span></div></div><div class="threat-banner-score"><b>${i.risk}</b><small>RISK</small></div><button class="btn danger sm" data-incident="${i.id}">View Attack Details</button></div>`:`<div class="threat-banner clear"><span class="threat-pulse"></span><div><div class="eyebrow">VPN STATUS</div><b>No active attack pattern detected</b><p>Monitoring authentication activity for rhythm, context and source relationships.</p></div></div>`;}
function liveEventRow(e){const status=eventStatus(e,S.incidents),risk=eventRisk(e,S.incidents),attack=status==='ATTACK DETECTED';return `<tr class="activity-row ${attack?'attack-row':''}" data-event-time="${esc(e.timestamp)}"><td class="mono">${new Date(e.timestamp).toLocaleTimeString()}</td><td><button class="link-button" data-entity="user" data-value="${esc(e.username)}">${esc(e.username)}</button></td><td><button class="link-button mono" data-entity="ip" data-value="${esc(e.source_ip)}">${esc(e.source_ip)}</button></td><td>${esc(countryName(e.country))}</td><td>${esc(e.device||e.user_agent||'Unknown')}</td><td><span class="result-pill ${e.result==='failure'?'fail':'pass'}">${e.result==='failure'?'FAILED':'SUCCESS'}</span></td><td><b class="risk-number ${risk>=80?'red-text':risk>=60?'amber-text':''}">${risk}</b></td><td><span class="event-state ${attack?'state-attack':status==='SUSPICIOUS'?'state-suspicious':'state-normal'}">${attack?'<i class="threat-dot"></i>':status==='SUSPICIOUS'?'●':'●'} ${status}</span></td></tr>`;}
function filteredActivity(){let rows=[...S.events];const f=S.activityFilter;if(S.range<1440&&rows.length){const latest=Math.max(...rows.map(e=>Date.parse(e.timestamp)));rows=rows.filter(e=>Date.parse(e.timestamp)>=latest-S.range*60000);}if(f.country!=='All')rows=rows.filter(e=>countryName(e.country)===f.country);if(f.device!=='All')rows=rows.filter(e=>e.device===f.device);if(f.result!=='All')rows=rows.filter(e=>e.result===f.result.toLowerCase());if(f.status!=='All')rows=rows.filter(e=>eventStatus(e,S.incidents)===f.status);if(f.type!=='All')rows=rows.filter(e=>S.incidents.some(i=>i.type===f.type&&i.events.includes(e)));if(f.severity!=='All')rows=rows.filter(e=>S.incidents.some(i=>i.severity===f.severity&&i.events.includes(e)));if(+f.minRisk)rows=rows.filter(e=>eventRisk(e,S.incidents)>=+f.minRisk);if(S.search){const q=S.search.toLowerCase();rows=rows.filter(e=>`${e.username} ${e.source_ip} ${e.country} ${e.device}`.toLowerCase().includes(q));}return rows.sort((a,b)=>Date.parse(b.timestamp)-Date.parse(a.timestamp));}
function activityFilters(){const countries=['All',...new Set(S.events.map(e=>countryName(e.country)))],devices=['All',...new Set(S.events.map(e=>e.device).filter(Boolean))],types=['All',...new Set(S.incidents.map(i=>i.type))];return `<div class="filters activity-filters"><select data-activity-filter="type">${types.map(x=>`<option ${S.activityFilter.type===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select data-activity-filter="severity">${['All','LOW','MEDIUM','HIGH','CRITICAL'].map(x=>`<option ${S.activityFilter.severity===x?'selected':''}>${x}</option>`).join('')}</select><select data-activity-filter="country">${countries.map(x=>`<option ${S.activityFilter.country===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select data-activity-filter="device">${devices.map(x=>`<option ${S.activityFilter.device===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select data-activity-filter="result">${['All','Success','Failure'].map(x=>`<option ${S.activityFilter.result===x?'selected':''}>${x}</option>`).join('')}</select><select data-activity-filter="status">${['All','NORMAL','SUSPICIOUS','ATTACK DETECTED'].map(x=>`<option ${S.activityFilter.status===x?'selected':''}>${x}</option>`).join('')}</select><select data-activity-filter="minRisk">${[['0','Any risk'],['30','Risk 30+'],['60','Risk 60+'],['80','Risk 80+']].map(([v,t])=>`<option value="${v}" ${String(S.activityFilter.minRisk)===v?'selected':''}>${t}</option>`).join('')}</select></div>`;}
function liveActivityCard(limit=12){const rows=filteredActivity().slice(0,limit);return `<div class="card live-activity-card">${cardTitle('Live VPN Login Activity',`${S.isMock?'SIMULATED LIVE DEMO STREAM':'Loaded dataset'} · newest events first · red marker means matched by an attack rule`)}${activityFilters()}<div class="table-wrap"><table><thead><tr><th>Time</th><th>User</th><th>Source IP</th><th>Country / region</th><th>Device / browser</th><th>Result</th><th>Risk</th><th>Detection status</th></tr></thead><tbody>${rows.map(liveEventRow).join('')||'<tr><td colspan="8" class="empty">No login events match these filters.</td></tr>'}</tbody></table></div></div>`;}
function explainCard(i){const d=detectionSignals(i,S.events);return `<div class="card alert-explain">${cardTitle('Why was this detected?','The rule evaluates RHYTHM + CONTEXT + SHAPE together.')}<div class="signal-grid"><div><span class="signal-label">RHYTHM</span><p>${esc(d.rhythm)}</p></div><div><span class="signal-label">CONTEXT</span><p>${esc(d.context)}</p></div><div><span class="signal-label">SHAPE</span><p>${esc(d.shape)}</p></div></div><p class="tiny muted">Confidence ${confidenceFor(i)}% is a rule-match strength indicator based on evidence and threshold margin; it is not a statistical accuracy guarantee.</p></div>`;}
function analystOverview(){const high=S.incidents.filter(i=>i.risk>=60).length,critical=S.incidents.filter(i=>i.risk>=80).length,suspicious=new Set(S.incidents.flatMap(i=>i.users)).size,fail=S.events.filter(e=>e.result==='failure').length,success=S.events.length-fail,confidence=S.incidents.length?Math.round(S.incidents.reduce((n,i)=>n+confidenceFor(i),0)/S.incidents.length):0,topIp=topCounts(S.events,'source_ip'),topUser=topCounts(S.events,'username'),hot=[...S.incidents].sort((a,b)=>b.risk-a.risk)[0];return `${head('VPN Security Overview',S.isMock?'Illustrative VPN authentication stream · simulated activity, not production telemetry':`Security monitoring · ${esc(S.datasetName)}`,`${typeBadge()}<span class="tag ${S.isMock?'demo':'good'}">${S.isMock?'SIMULATED LIVE':'DATA LOADED'}</span><button class="btn secondary sm" data-page="Dataset">Load authentication logs</button>`)}${liveStatus()}<div class="grid stats analyst-stats">${stat('Total login attempts',S.events.length,'↗')}${stat('Successful logins',success,'✓')}${stat('Failed logins',fail,'×')}${stat('Suspicious users',suspicious,'♙')}${stat('Active threats',S.incidents.length,'⚑')}${stat('Critical threats',critical,'!')}${stat('Unique source IPs',new Set(S.events.map(e=>e.source_ip)).size,'⌖')}${stat('Detection confidence',confidence?`${confidence}%`:'—','◎','Heuristic rule-match strength')}</div>${hot?explainCard(hot):`<div class="card rhythm-card"><b>Detection model</b><p>SprayScope correlates <b>RHYTHM</b> (timing and frequency), <b>CONTEXT</b> (users, locations, devices), and <b>SHAPE</b> (source-to-user relationships). A single failed login never creates an attack incident.</p></div>`}<div class="grid cols"><div>${activityCard()}${liveActivityCard(10)}</div><div><div class="card">${cardTitle('Top suspicious source IPs','Ranked by event volume; open an IP to inspect evidence')}${topIp.slice(0,5).map(([ip,n])=>`<div class="rank-row"><button class="link-button mono" data-entity="ip" data-value="${esc(ip)}">${esc(ip)}</button><span>${n} events</span><span class="risk-chip ${S.incidents.some(i=>i.source_ip===ip)?'risk-hot':''}">${S.incidents.find(i=>i.source_ip===ip)?.risk??Math.min(59,n*3)} risk</span></div>`).join('')}</div><div class="card">${cardTitle('Most targeted / active users','Select a user for authentication history')}${topUser.slice(0,5).map(([u,n])=>`<div class="rank-row"><button class="link-button" data-entity="user" data-value="${esc(u)}">${esc(u)}</button><span>${n} logins</span><span class="muted">${S.incidents.some(i=>i.users.includes(u))?'THREAT':'NORMAL'}</span></div>`).join('')}</div><div class="card">${cardTitle('Attack mix','Detected pattern categories')}${S.incidents.map(i=>`<div class="rank-row"><span>${esc(i.type)}</span><span>${i.users.length} users</span>${sev(i.severity)}</div>`).join('')||'<p class="tiny muted">No attack rules have triggered.</p>'}<button class="btn secondary sm" data-page="Attack Graph">Open Attack Source Graph</button></div></div></div>`;}
function analystVisualCards(){const geo=new Map();for(const e of S.events){const name=countryName(e.country);geo.set(name,(geo.get(name)||0)+1);}const geos=[...geo.entries()].sort((a,b)=>b[1]-a[1]).slice(0,5),maxGeo=Math.max(1,...geos.map(x=>x[1])),buckets=[['LOW',0,29],['MEDIUM',30,59],['HIGH',60,79],['CRITICAL',80,100]].map(([label,lo,hi])=>[label,S.events.filter(e=>{const n=eventRisk(e,S.incidents);return n>=lo&&n<=hi;}).length]);return `<div class="grid three"><div class="card">${cardTitle('Geographic distribution','Country values are shown only when present in the source events')}${geos.map(([name,n])=>`<div class="dist-row"><span>${esc(name)}</span><div class="bar"><i style="width:${Math.round(n/maxGeo*100)}%"></i></div><b>${n}</b></div>`).join('')}</div><div class="card">${cardTitle('Risk score distribution','Explainable rule score per event')}${buckets.map(([name,n])=>`<div class="dist-row"><span class="severity ${name.toLowerCase()}">${name}</span><div class="bar"><i class="risk-bar-${name.toLowerCase()}" style="width:${Math.max(n?4:0,Math.round(n/Math.max(1,S.events.length)*100))}%"></i></div><b>${n}</b></div>`).join('')}</div><div class="card">${cardTitle('Detection capabilities','Signals are rule-based; no ML accuracy claim')}${[['Password Spraying','T1110.003'],['Brute Force','T1110.001'],['Impossible Travel','T1078'],['Credential Stuffing','T1110.004'],['Distributed Brute Force','T1110.001'],['Account Enumeration','T1087'],['Abnormal Login Burst','T1110']].map(([name,mitre])=>`<div class="rank-row"><span>${name}</span><span class="mono">${mitre}</span></div>`).join('')}</div></div>`;}
function attackDetailEnhancement(i){const d=detectionSignals(i,S.events);return `<div class="grid two"><div>${explainCard(i)}<div class="card">${cardTitle('Recommended analyst action')}<ul class="recommend-list"><li>Investigate and enrich the source IP using trusted threat intelligence.</li><li>Review authentication logs and VPN gateway records for the affected time window.</li><li>Require affected users to re-authenticate and verify MFA coverage.</li><li>Consider temporarily blocking the source after analyst validation.</li></ul><div class="row"><span class="tag ${i.risk>=80?'bad':i.risk>=60?'demo':'good'}">RISK ${i.risk}/100 · ${i.severity}</span><span class="tag">RULE CONFIDENCE ${confidenceFor(i)}%</span></div></div></div><div><div class="card">${cardTitle('Attack evidence summary')}<div class="detail-list"><div><span>Attack type</span><b>${esc(i.type)}</b></div><div><span>Severity / risk</span><b>${i.severity} · ${i.risk}/100</b></div><div><span>Rule confidence</span><b>${confidenceFor(i)}%</b></div><div><span>Affected users</span><b>${i.users.length}</b></div><div><span>Source IPs</span><b>${[...new Set(i.events.map(e=>e.source_ip))].length}</b></div><div><span>First / last seen</span><b>${time(i.first_seen)}<br>${time(i.last_seen)}</b></div><div><span>MITRE ATT&CK</span><b>${esc(i.mitre)}</b></div></div><p class="tiny muted">${esc(d.rhythm)} ${esc(d.shape)}</p></div><div class="card">${cardTitle('Attack path')}<button class="btn secondary sm" data-action="focusGraph" data-id="${i.id}">Open related source graph</button><button class="btn sm" data-action="replay" data-id="${i.id}">Investigate / Replay Attack</button></div></div></div>`;}
function entityRiskMarkup(risk,status){return `<span class="entity-risk ${risk>=80?'risk-critical':risk>=60?'risk-high':risk>=30?'risk-medium':'risk-low'}">${risk}/100 · ${status}</span>`;}
function entityInvestigation(){const {kind,value}=S.entity;if(kind==='user'){const d=userSummary(value,S.events,S.incidents);return `${head('User Investigation',`${esc(d.user)} · login behavior and related threat evidence`,entityRiskMarkup(d.risk,d.status))}<div class="grid stats">${stat('Login attempts',d.rows.length,'↗')}${stat('Failed logins',d.failed,'×')}${stat('Successful logins',d.successes,'✓')}${stat('Source IPs',d.ips.length,'⌖')}</div><div class="grid two"><div class="card">${cardTitle('Authentication history')}<div class="detail-list"><div><span>User</span><b>${esc(d.user)}</b></div><div><span>Devices</span><b>${d.devices.map(esc).join(', ')||'Unknown'}</b></div><div><span>Locations</span><b>${d.locations.map(esc).join(', ')||'Unknown'}</b></div><div><span>Source IP history</span><b>${d.ips.map(ip=>`<button class="link-button mono" data-entity="ip" data-value="${esc(ip)}">${esc(ip)}</button>`).join(', ')}</b></div><div><span>Detected attack types</span><b>${d.attacks.map(esc).join(', ')||'None'}</b></div><div><span>Related suspicious users</span><b>${d.relatedUsers.map(esc).join(', ')||'None in loaded data'}</b></div></div></div><div class="card">${cardTitle('Recent login attempts')}${loginEventTable(d.rows)}</div></div><div class="card">${cardTitle('Analyst assessment')}<p>${d.status==='NORMAL'?'No current attack relationship was detected for this user in the loaded sample.':`This user is linked to ${d.attacks.join(', ')}. Review source IPs, MFA events, and recent successful sessions.`}</p><p class="tiny muted">MITRE: ${S.incidents.filter(i=>i.users.includes(value)).map(i=>i.mitre).join(', ')||'No technique mapped'} · risk derives from linked incident evidence and failed-login volume.</p><button class="btn secondary sm" data-action="backOverview">← Security overview</button></div>`;}const d=ipSummary(value,S.events,S.incidents);return `${head('Source Investigation',`${esc(d.ip)} · source activity and targeted identities`,entityRiskMarkup(d.risk,d.attacks.length?'ATTACK DETECTED':d.failed?'SUSPICIOUS':'NORMAL'))}<div class="grid stats">${stat('Total attempts',d.rows.length,'↗')}${stat('Failed attempts',d.failed,'×')}${stat('Successful attempts',d.successes,'✓')}${stat('Users targeted',d.users.length,'♙')}</div><div class="grid two"><div class="card">${cardTitle('Source profile')}<div class="detail-list"><div><span>IP address</span><b class="mono">${esc(d.ip)}</b></div><div><span>Country / region</span><b>${d.locations.map(esc).join(', ')||'Unknown (not geolocated)'}</b></div><div><span>First seen</span><b>${time(d.firstSeen)}</b></div><div><span>Last seen</span><b>${time(d.lastSeen)}</b></div><div><span>Devices used</span><b>${d.devices.map(esc).join(', ')||'Unknown'}</b></div><div><span>Attack types</span><b>${d.attacks.map(i=>esc(i.type)).join(', ')||'None'}</b></div><div><span>ASN / network</span><b>Unavailable in loaded logs</b></div></div><button class="btn secondary sm" data-action="focusIpGraph" data-value="${esc(d.ip)}">Open Attack Source Graph</button></div><div class="card">${cardTitle('Source → users')}${d.users.map(u=>`<div class="rank-row"><button class="link-button" data-entity="user" data-value="${esc(u)}">${esc(u)}</button><span>${d.rows.filter(e=>e.username===u).length} attempts</span><span>${d.rows.filter(e=>e.username===u&&e.result==='failure').length} failures</span></div>`).join('')}</div></div><div class="card">${cardTitle('Source timeline')}${loginEventTable(d.rows)}</div>${d.attacks.map(i=>attackDetailEnhancement(i)).join('')||''}`;}
function loginEventTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Time</th><th>User</th><th>Source IP</th><th>Location</th><th>Device</th><th>Result</th><th>Risk</th></tr></thead><tbody>${[...rows].sort((a,b)=>Date.parse(b.timestamp)-Date.parse(a.timestamp)).map(e=>`<tr class="${eventStatus(e,S.incidents)==='ATTACK DETECTED'?'attack-row':''}"><td>${time(e.timestamp)}</td><td><button class="link-button" data-entity="user" data-value="${esc(e.username)}">${esc(e.username)}</button></td><td><button class="link-button mono" data-entity="ip" data-value="${esc(e.source_ip)}">${esc(e.source_ip)}</button></td><td>${esc(countryName(e.country))}</td><td>${esc(e.device||'Unknown')}</td><td>${esc(e.result)}</td><td>${eventRisk(e,S.incidents)}</td></tr>`).join('')}</tbody></table></div>`;}
function attackSourceGraph(){if(!S.incidents.length)return `${head('Attack Source Graph','Relationships among VPN sources, users, devices, locations and gateway.') }<div class="card empty">No attack relationships to graph yet. Load demo logs or analyze a dataset.</div>`;let i=S.incidents.find(x=>x.id===S.graphIncidentId)||[...S.incidents].sort((a,b)=>b.risk-a.risk)[0];const users=i.users.slice(0,8),source=i.source_ip||i.events[0]?.source_ip,loc=countryName(i.events.find(e=>e.country)?.country),device=i.events.find(e=>e.device)?.device||'Unknown device',cx=450,cy=180,r=112,points=users.map((u,n)=>({u,x:cx+Math.cos(-Math.PI/2+2*Math.PI*n/users.length)*r,y:cy+Math.sin(-Math.PI/2+2*Math.PI*n/users.length)*r}));return `${head('Attack Source Graph','Attack paths connect source IPs to users, devices, locations and VPN gateways.',typeBadge())}<div class="card"><div class="filters"><select id="graphSelect">${S.incidents.map(x=>`<option value="${x.id}" ${x.id===i.id?'selected':''}>${esc(x.type)} · ${esc(x.source_ip)}</option>`).join('')}</select><button class="btn secondary sm" data-action="zoomIn">＋</button><button class="btn secondary sm" data-action="zoomOut">−</button><button class="btn ghost sm" data-action="resetZoom">Reset</button></div><div class="graph-layout"><div class="graph-area" id="graphArea"><svg viewBox="0 0 900 410"><g transform="translate(${S.pan.x} ${S.pan.y}) scale(${S.zoom})">${points.map(p=>`<line class="edge edge-attack" x1="${cx}" y1="${cy}" x2="${p.x}" y2="${p.y}"/>`).join('')}<line class="edge edge-context" x1="${cx}" y1="${cy}" x2="${cx-165}" y2="70"/><line class="edge edge-context" x1="${cx}" y1="${cy}" x2="${cx+160}" y2="345"/><line class="edge edge-context" x1="${cx}" y1="${cy}" x2="770" y2="180"/>${points.map((p,n)=>`<line class="edge edge-context" x1="${p.x}" y1="${p.y}" x2="${p.x}" y2="${Math.min(375,p.y+65)}"/>`).join('')}<g class="graph-node graph-node-attack" data-entity="ip" data-value="${esc(source)}"><circle cx="${cx}" cy="${cy}" r="34"/><text x="${cx}" y="${cy-2}">SOURCE IP</text><text class="node-small" x="${cx}" y="${cy+12}">${esc(source)}</text></g>${points.map(p=>`<g class="graph-node graph-node-user" data-entity="user" data-value="${esc(p.u)}"><circle cx="${p.x}" cy="${p.y}" r="23"/><text x="${p.x}" y="${p.y+4}">${esc(p.u.split('.')[0])}</text></g><g class="graph-node graph-node-device" data-entity="device" data-value="${esc(device)}"><circle cx="${p.x}" cy="${Math.min(375,p.y+65)}" r="15"/><text class="node-small" x="${p.x}" y="${Math.min(375,p.y+88)}">DEVICE</text></g>`).join('')}<g class="graph-node graph-node-location" data-entity="location" data-value="${esc(loc)}"><circle cx="${cx-165}" cy="70" r="25"/><text x="${cx-165}" y="74">${esc(loc.slice(0,11))}</text></g><g class="graph-node graph-node-gateway" data-entity="gateway" data-value="VPN Gateway"><circle cx="770" cy="180" r="27"/><text x="770" y="184">VPN GW</text></g></g></svg></div><aside class="graph-detail card">${cardTitle('Selected attack path')}<b>${esc(i.type)}</b><p>${esc(i.reason)}</p><div class="detail-list"><div><span>Source</span><b class="mono">${esc(source)}</b></div><div><span>Users targeted</span><b>${i.users.length}</b></div><div><span>Devices</span><b>${new Set(i.events.map(e=>e.device).filter(Boolean)).size}</b></div><div><span>Location</span><b>${esc(loc)}</b></div><div><span>Risk / confidence</span><b>${i.risk}/100 · ${confidenceFor(i)}%</b></div></div><p class="tiny muted">Red edges are attack evidence. Blue-gray edges are contextual relationships from the loaded events.</p></aside></div></div>`;}
function authenticationTimeline(){const rows=filteredActivity(),replay=S.replay,attackByEvent=new Map();for(const i of S.incidents)for(const e of i.events)attackByEvent.set(e,i);return `${head('Authentication Timeline','Chronological login activity with the first matched event and attack classification.',typeBadge())}${replay?replayPanel():''}<div class="card">${cardTitle('Timeline controls','Filter the event stream and replay an incident in sequence')}<div class="filters"><select id="range">${[5,10,30,60,1440].map(x=>`<option value="${x}" ${S.range===x?'selected':''}>${x<60?x+' min':x===60?'1 hour':'24 hours'}</option>`).join('')}</select><button class="btn secondary sm" data-action="replayLatest">▶ Replay latest attack</button><button class="btn ghost sm" data-page="Attack Graph">Open source graph</button></div>${activityFilters()}<div class="table-wrap"><table><thead><tr><th>Time</th><th>User</th><th>Source IP</th><th>Action</th><th>Result</th><th>Risk</th><th>Attack classification</th></tr></thead><tbody>${rows.map((e,n)=>{const i=attackByEvent.get(e),playing=replay?.events[replay.index]===e;return `<tr class="${playing?'replay-current':i?'attack-row':''}"><td class="mono">${time(e.timestamp)}${i&&i.events[0]===e?' <span class="threat-dot"></span>':''}</td><td><button class="link-button" data-entity="user" data-value="${esc(e.username)}">${esc(e.username)}</button></td><td><button class="link-button mono" data-entity="ip" data-value="${esc(e.source_ip)}">${esc(e.source_ip)}</button></td><td>LOGIN</td><td>${esc(e.result).toUpperCase()}</td><td>${eventRisk(e,S.incidents)}</td><td>${i?`<b class="red-text">${esc(i.type)} DETECTED</b>`:esc(eventStatus(e,S.incidents))}</td></tr>`;}).join('')}</tbody></table></div></div>`;}
function replayPanel(){const r=S.replay,idx=Math.min(r.index,r.events.length-1),e=r.events[idx],stage=idx>=r.events.length-1?'PATTERN RECOGNIZED':idx===0?'SOURCE DETECTED':idx<r.events.length-1?`USER ${idx} TARGETED`:'ATTACK CLASSIFIED';return `<div class="card replay-card"><div class="row"><div><div class="eyebrow red-text">ATTACK REPLAY · ${esc(r.type)}</div><h3>${stage}</h3><p class="tiny muted">Event ${Math.min(idx+1,r.events.length)} of ${r.events.length} · ${e?`${esc(e.username)} from ${esc(e.source_ip)}`:''}</p></div><button class="btn ghost sm" data-action="stopReplay">Close replay</button></div><div class="progress"><i style="width:${Math.min(100,(idx+1)/r.events.length*100)}%"></i></div><p class="tiny">${idx>=r.events.length-1?'SprayScope correlated the sequence and classified the attack.':'Following the source-to-user events in timestamp order…'}</p></div>`;}
function incidentEnhancement(i){return attackDetailEnhancement(i)+`<div class="card">${cardTitle('Authentication attack progression')}<button class="btn sm" data-action="replay" data-id="${i.id}">Investigate Attack / Replay</button><button class="btn secondary sm" data-action="focusGraph" data-id="${i.id}">View Attack Source Graph</button></div>`;}
function fixtureChooser(){return `<div class="card"><div class="card-title"><div><h3>Attack-specific demo datasets</h3><p>Har dataset mein sirf ek labelled attack type hai. Load karke mapping review karein, phir Confirm & Analyze karein.</p></div><span class="tag synthetic">SYNTHETIC LABELLED DATA</span></div><div class="grid three">${[['brute-force-only.csv','Brute Force','10 failed logins target one account · T1110.001'],['password-spray-only.csv','Password Spray','12 accounts targeted from one source · T1110.003'],['impossible-travel-only.csv','Impossible Travel','Successful US and GB logins one minute apart · T1078']].map(([file,title,desc])=>`<div class="card" style="margin:0;background:#0a1726"><div class="eyebrow">ONE ATTACK TYPE</div><h3 style="font-size:14px">${title}</h3><p class="tiny muted">${desc}</p><div class="actions"><button class="btn sm" data-fixture="${file}">Load dataset</button><a class="btn secondary sm" href="dataset/${file}" download>Download CSV</a></div></div>`).join('')}</div><p class="tiny muted" style="margin-top:12px">These labelled files are synthetic hackathon test fixtures, not live or real-world incident data. Ground truth is included so the Metrics page can calculate evaluation values.</p></div>`;}
function renderStandalonePortal(){publicPortal=true;document.body.classList.add('portal-mode');app.innerHTML=`<main class="portal-public">${userPortal()}</main>`;loadObservedClientIp();}
function readPortalEvents(){try{return JSON.parse(localStorage.getItem('sprayscope-portal-events')||'[]');}catch{return [];}}
function userPortal(){const actions=publicPortal?'<a class="btn secondary sm" href="./">Analyst sign in</a>':`<span class="tag demo">LOCAL ATTACK SIMULATOR</span><button class="btn secondary sm" data-page="Overview">Back to SOC Dashboard</button>`;return `${head('Employee VPN Sign In','A safe local simulation portal. Submit sign-ins here to create authentication events on the analyst dashboard.',actions)}<div class="portal-notice"><b>Training sandbox</b><span>This page does not connect to a VPN or verify real identities. Use the comparison button to record two fictional accounts: one accepted and one rejected. Passwords are never stored. The source IP below is observed by this backend; on localhost it will be a loopback address, not your public internet IP.</span></div><div class="portal-layout"><div class="card portal-login-card"><div class="portal-brand"><span class="portal-shield">◈</span><div><b>CYBERNOVA</b><small>REMOTE ACCESS GATEWAY</small></div></div><h2>Sign in to your VPN</h2><p class="muted">Use the form for a single simulated attempt, or record the ready-made comparison pair.</p><div class="portal-comparison"><b>Demo identities</b><span>Accepted: <code>employee.success@cybernova.test</code></span><span>Rejected: <code>employee.failed@cybernova.test</code></span><button class="btn secondary" type="button" data-portal-pair>Record success + failure comparison</button><small>Creates two sample events without requiring or saving a password.</small></div><form id="vpnPortalForm" class="portal-form"><label>Work email<input class="field" type="email" name="portalUser" placeholder="alex@cybernova.test" value="${esc(S.userName.includes('@')?S.userName:'alex@cybernova.test')}" required></label><label>Password<input class="field" type="password" name="portalPassword" autocomplete="off" placeholder="Password (never stored)" required></label><div class="grid two"><label>Simulated location<select class="field" name="portalCountry"><option value="US">United States</option><option value="GB">United Kingdom</option><option value="DE">Germany</option><option value="IN">India</option></select></label><label>Simulated result<select class="field" name="portalResult"><option value="failure">Rejected sign-in (attack test)</option><option value="success">Accepted sign-in (normal activity)</option></select></label></div><label>Source IP observed by backend<input class="field" name="portalIp" value="203.0.113.250" required pattern="[0-9a-fA-F:.]+" title="Enter a valid IP address"><small id="portalIpNote" class="tiny muted">Checking the address seen by this server…</small></label><button class="btn" type="submit">Submit Sign In</button></form><div class="portal-response" id="portalResponse" aria-live="polite">Ready · submissions are visible to the analyst dashboard.</div></div><div class="card"><div class="card-title"><div><h3>Run an attack scenario</h3><p>Generate realistic event patterns against the simulated portal.</p></div></div><label>Target account<input class="field" id="portalTarget" type="email" value="alex@cybernova.test"></label><div class="portal-scenarios"><button class="btn danger" data-action="portalBrute">Run brute-force test<span>12 failed attempts · one account</span></button><button class="btn danger" data-action="portalSpray">Run password-spray test<span>12 accounts · one source</span></button><button class="btn secondary" data-action="portalTravel">Run impossible-travel test<span>Two accepted logins · US then UK</span></button></div><div class="portal-foot">Dashboard detections run against these generated events immediately. All accounts and outcomes are fictional. Source IP is the address this server observes, not a geolocation result.</div></div></div>`;}
function addPortalEvents(events){const stored=readPortalEvents(),ids=new Set(stored.map(e=>e.portal_event_id));for(const e of events)if(!ids.has(e.portal_event_id)){stored.push(e);ids.add(e.portal_event_id);}const capped=stored.slice(-800);localStorage.setItem('sprayscope-portal-events',JSON.stringify(capped));const existing=new Set(S.events.map(e=>e.portal_event_id).filter(Boolean));S.events.push(...events.filter(e=>!existing.has(e.portal_event_id)));S.events=S.events.slice(-1000);S.events=S.events.map(e=>({...e,label:null}));S.raw=[];S.source='demo';S.isMock=S.datasetName.includes('analyst demo')||S.isMock;S.datasetName=S.isMock?'VPN analyst demo + user portal attempts':'VPN user portal simulation';S.incidents=runDetection(S.events);S.status='Complete';S.selected=null;S.entity=null;return fetch('/api/events',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({events})}).then(r=>{if(!r.ok)throw new Error('API unavailable');backendOnline=true;return true;}).catch(()=>false);}
async function syncBackendEvents(){try{const response=await fetch('/api/events',{cache:'no-store'});if(!response.ok)throw new Error('API unavailable');const incoming=(await response.json()).events||[],known=new Set(S.events.map(e=>e.portal_event_id).filter(Boolean)),fresh=incoming.filter(e=>!known.has(e.portal_event_id));if(fresh.length){S.events.push(...fresh.map(e=>({...e,label:null})));S.events=S.events.slice(-1000);S.source='demo';S.datasetName='VPN analyst demo + user portal attempts';S.incidents=runDetection(S.events);S.status='Complete';if(S.page==='Overview'&&!S.selected&&!S.entity)renderPage();}backendOnline=true;if(S.logged&&!window.__sprayscopeBackendPoll)window.__sprayscopeBackendPoll=setInterval(syncBackendEvents,5000);return true;}catch{backendOnline=false;return false;}}
function makePortalEvent({user,ip='203.0.113.250',country='US',result='failure',minute=0,scenario='manual'}){const timestamp=new Date(Date.now()+minute*1000).toISOString();return {portal_event_id:crypto.randomUUID(),timestamp,username:user,source_ip:ip,country,device:'Browser / VPN portal simulator',user_agent:`${navigator.userAgent.slice(0,100)} · SprayScope simulator`,result,action:'VPN_SIGN_IN',simulation:'user-portal',scenario,label:null};}
async function loadObservedClientIp(){const field=document.querySelector('[name="portalIp"]'),note=document.querySelector('#portalIpNote'),pair=document.querySelector('[data-portal-pair]');if(!field)return;if(pair)pair.disabled=true;try{const response=await fetch('/api/client-info',{cache:'no-store'});if(!response.ok)throw Error('backend unavailable');const info=await response.json();if(!info.source_ip||info.source_ip==='unknown')throw Error('source address unavailable');field.value=info.source_ip;if(note)note.textContent=`Server-observed connection address: ${info.source_ip}. Localhost connections appear as loopback.`;if(pair)pair.disabled=false;}catch{if(note)note.textContent='Auto-detection unavailable. The current value is a demo-only placeholder; edit it to your IP before recording. Public IP lookup is not performed.';if(pair)pair.disabled=false;}}
function recordPortalComparison(){const ip=String(document.querySelector('[name="portalIp"]')?.value||'').trim();if(!ip)return;const events=[makePortalEvent({user:'employee.success@cybernova.test',ip,country:'US',result:'success',scenario:'comparison-demo'}),makePortalEvent({user:'employee.failed@cybernova.test',ip,country:'US',result:'failure',scenario:'comparison-demo'})];const sync=addPortalEvents(events),response=document.querySelector('#portalResponse');if(response)response.textContent=`Recording accepted and rejected demo sign-ins from ${ip}…`;sync.then(saved=>{const current=document.querySelector('#portalResponse');if(current)current.textContent=`Comparison recorded: employee.success@cybernova.test accepted; employee.failed@cybernova.test rejected · source ${ip} · ${saved?'shared with dashboard':'saved in this browser; backend is offline'}.`;});}
function submitPortalLogin(form){const data=new FormData(form),user=String(data.get('portalUser')||'').trim().toLowerCase(),ip=String(data.get('portalIp')||'203.0.113.250').trim(),country=String(data.get('portalCountry')||'US'),result=String(data.get('portalResult')||'failure');if(!user||!ip)return;const password=String(data.get('portalPassword')||'');if(!password)return;const sync=addPortalEvents([makePortalEvent({user,ip,country,result})]);form.reset();loadObservedClientIp();const response=document.querySelector('#portalResponse');if(response)response.textContent=`${result==='failure'?'Rejected':'Accepted'} · ${user} · saving event…`;sync.then(saved=>{const current=document.querySelector('#portalResponse');if(current)current.textContent=`${result==='failure'?'Rejected':'Accepted'} · ${user} · ${saved?'saved to shared backend':'saved in this browser; backend is offline'}`;});toast('Sign-in attempt recorded.');}
function runPortalScenario(kind){const input=document.querySelector('#portalTarget'),target=(input?.value||'alex@cybernova.test').trim().toLowerCase(),events=[],ip='203.0.113.250';if(kind==='portalBrute'){for(let n=0;n<12;n++)events.push(makePortalEvent({user:target,ip,country:'US',result:'failure',minute:n*4,scenario:'brute-force'}));}else if(kind==='portalSpray'){for(let n=0;n<12;n++)events.push(makePortalEvent({user:`user${String(n+1).padStart(2,'0')}@cybernova.test`,ip,country:'DE',result:'failure',minute:n*4,scenario:'password-spray'}));}else {events.push(makePortalEvent({user:target,ip:'198.51.100.240',country:'US',result:'success',minute:0,scenario:'impossible-travel'}),makePortalEvent({user:target,ip:'203.0.113.251',country:'GB',result:'success',minute:20,scenario:'impossible-travel'}));}addPortalEvents(events);if(publicPortal){const response=document.querySelector('#portalResponse');if(response)response.textContent=`${events.length} ${kind==='portalBrute'?'brute-force':kind==='portalSpray'?'password-spray':'impossible-travel'} events sent. Open the analyst dashboard in another tab to investigate.`;}else{S.page='Overview';document.querySelectorAll('.nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===S.page));renderPage();}toast(`${kind==='portalBrute'?'Brute-force':kind==='portalSpray'?'Password-spray':'Impossible-travel'} test events added to the dashboard.`);}
function pageHTML(){if(S.entity)return entityInvestigation();if(S.selected){const i=S.incidents.find(x=>x.id===S.selected);if(i)return investigation(i)+incidentEnhancement(i);}switch(S.page){case'User VPN Portal':return userPortal();case'Dataset':return dataset()+fixtureChooser();case'Analyze Logs':return analyzeView();case'Incidents':return incidentList();case'Activity Timeline':return authenticationTimeline();case'Attack Graph':return attackSourceGraph();case'Metrics':return metrics();case'Reports':return reports();case'Settings':return settings();default:return analystOverview()+analystVisualCards();}}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{S.page=b.dataset.page;S.selected=null;renderPage();});document.querySelectorAll('[data-incident]').forEach(el=>el.onclick=()=>{S.selected=el.dataset.incident;S.page='Incidents';renderPage();});document.querySelectorAll('[data-map]').forEach(el=>el.onchange=()=>{S.map[el.dataset.map]=el.value;updateNormalized();renderPage();});const file=document.querySelector('#file');if(file)file.onchange=()=>loadFile(file.files[0]);const drop=document.querySelector('#drop');if(drop){drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag');};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');loadFile(e.dataTransfer.files[0]);};}const range=document.querySelector('#range');if(range)range.onchange=()=>{S.range=+range.value;renderPage();};const tf=document.querySelector('#typeFilter');if(tf)tf.onchange=()=>{S.filter.type=tf.value;renderPage();};const sf=document.querySelector('#sevFilter');if(sf)sf.onchange=()=>{S.filter.severity=sf.value;renderPage();};const sort=document.querySelector('#sort');if(sort)sort.onchange=()=>{if(sort.value==='new')S.incidents.sort((a,b)=>Date.parse(b.first_seen)-Date.parse(a.first_seen));else if(sort.value==='users')S.incidents.sort((a,b)=>b.users.length-a.users.length);else S.incidents.sort((a,b)=>b.risk-a.risk);renderPage();};const gs=document.querySelector('#graphSelect');if(gs)gs.onchange=()=>{S.selected=gs.value;renderPage();};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id));document.querySelectorAll('[data-node]').forEach(n=>n.onclick=()=>{const val=n.dataset.node,inc=S.incidents.find(x=>x.source_ip===val||x.users.includes(val));if(inc){S.selected=inc.id;renderPage();}});const area=document.querySelector('#graphArea');if(area){let start;area.onpointerdown=e=>{start=[e.clientX,e.clientY,S.pan.x,S.pan.y];area.setPointerCapture(e.pointerId);};area.onpointermove=e=>{if(start){S.pan={x:start[2]+e.clientX-start[0],y:start[3]+e.clientY-start[1]};const g=area.querySelector('g');g.setAttribute('transform',`translate(${S.pan.x} ${S.pan.y}) scale(${S.zoom})`);}};area.onpointerup=()=>start=null;}}
function renderPage(){if(!S.logged)return login();const el=document.querySelector('#content');if(!el)return shell();el.innerHTML=pageHTML();bind();if(S.page==='User VPN Portal')loadObservedClientIp();}
function render(){if(S.logged){ensureAnalystMock();shell();syncBackendEvents();}else login();}
function ensureAnalystMock(){if(!S.events.length&&S.source==='demo'){const portal=readPortalEvents();S.events=[...createAnalystMock(),...portal];S.datasetName=portal.length?'VPN analyst demo + user portal attempts':'VPN analyst demo stream';S.isMock=true;S.incidents=runDetection(S.events);S.status='Complete';}if(S.isMock&&!window.__sprayscopeMockTimer){window.__sprayscopeMockTimer=setInterval(()=>{if(!S.logged||!S.isMock)return;const users=['maria.chen','john.doe','alice.rao','sam.patel','nina.khan','omar.hassan','maya.jones'];const ips=['198.51.100.10','198.51.100.11','198.51.100.12','203.0.113.88'];const user=users[Math.floor(Math.random()*users.length)],source=ips[Math.floor(Math.random()*ips.length)],failed=Math.random()<.27;S.events.push({timestamp:new Date().toISOString(),username:user,source_ip:source,country:source==='203.0.113.88'?'DE':'US',device:source==='203.0.113.88'?'Unknown / VPN client':'Windows / Chrome',user_agent:source==='203.0.113.88'?'Unknown client':'Windows / Chrome',result:failed?'failure':'success',action:'LOGIN'});if(S.events.length>500)S.events.splice(0,S.events.length-500);S.incidents=runDetection(S.events);S.status='Complete';if(S.page==='Overview'&&!S.selected&&!S.entity)renderPage();},9000);}}
function updateNormalized(){S.events=normalize(S.raw,S.map);S.incidents=[];S.status='Idle';S.isMock=false;}
async function loadFile(file){if(!file)return;try{const text=await file.text();let rows;if(file.name.toLowerCase().endsWith('.csv'))rows=parseCSV(text);else if(file.name.toLowerCase().endsWith('.json')){const j=JSON.parse(text);rows=Array.isArray(j)?j:j.events||j.records||[j];}else{try{const j=JSON.parse(text);rows=Array.isArray(j)?j:j.events||j.records||[j];}catch{rows=parseCSV(text);}}if(!rows.length)throw Error('No rows were found.');S.raw=rows;S.columns=Object.keys(rows[0]);S.map=guessMap(rows);S.datasetName=file.name;S.source=rows.some(r=>r.label||r.ground_truth||r.groundTruth)?'synthetic':'real';updateNormalized();S.page='Dataset';renderPage();toast(`Loaded ${rows.length} rows. Review column mapping before analysis.`);}catch(e){toast(`Could not load file: ${e.message}`);}}
async function loadFixture(file){try{const response=await fetch(`dataset/${file}`);if(!response.ok)throw Error(`HTTP ${response.status}`);const rows=parseCSV(await response.text());if(!rows.length)throw Error('The fixture contains no rows.');S.raw=rows;S.columns=Object.keys(rows[0]);S.map=guessMap(rows);S.events=normalize(rows,S.map);S.datasetName=file;S.source='synthetic';S.isMock=false;S.incidents=[];S.status='Idle';S.selected=null;S.page='Dataset';renderPage();toast(`${file}: ${rows.length} labelled events loaded. Continue to mapping and run detection.`);}catch(e){toast(`Could not load demo dataset: ${e.message}`);}}
function loadDemo(){S.events=createDemo().map(({label,...e})=>e);S.raw=S.events.map(e=>({...e}));S.columns=Object.keys(S.raw[0]);S.map=guessMap(S.raw);S.datasetName='sprayscope-auth-demo.json';S.source='demo';S.isMock=false;S.incidents=[];S.status='Idle';S.page='Dataset';renderPage();toast('Local mixed demonstration sample loaded. No LogHub corpus was downloaded.');}
function generated(type='mix',usersN=40,eventsN=300,intensity=2,duration=10){const ev=[],now=Date.now()-duration*60000,users=Array.from({length:usersN},(_,i)=>`user${i+1}@synthetic.test`),ips=Array.from({length:Math.max(3,Math.floor(usersN/5))},(_,i)=>`198.51.100.${i+1}`);const add=(minute,u,ip,result,label='normal',country='US')=>ev.push({timestamp:new Date(now+minute*60000).toISOString(),username:u,source_ip:ip,result,country,user_agent:'Synthetic VPN Agent',device:'Test Device',label});for(let i=0;i<eventsN;i++){const u=users[Math.floor(Math.random()*users.length)],t=Math.random()*duration;add(t,u,ips[Math.floor(Math.random()*ips.length)],Math.random()<.83?'success':'failure');}const attack=type==='mix'?['brute_force','password_spray'][Math.floor(Math.random()*2)]:type;if(attack==='brute_force'||attack==='password_spray'){const n=Math.max(10,10*intensity),start=Math.max(0,duration*.35);for(let i=0;i<n;i++){const u=attack==='brute_force'?users[0]:users[i%Math.max(10,Math.min(users.length,30))];add(start+Math.random()*Math.min(5,duration),u,attack==='brute_force'?ips[0]:'203.0.113.250','failure',attack);}}if(attack==='impossible_travel'){add(duration*.2,users[0],ips[0],'success','impossible_travel','US');add(duration*.2+1,users[0],ips[1],'success','impossible_travel','GB');}if(type==='normal')return ev.map(e=>({...e,label:'normal'}));return ev.sort((a,b)=>Date.parse(a.timestamp)-Date.parse(b.timestamp));}
function loadSynthetic(kind){let type=kind==='demoSpray'?'password_spray':kind==='demoBrute'?'brute_force':kind==='demoTravel'?'impossible_travel':'password_spray';let e;if(kind==='demoSpray')e=generated(type,40,200,3,10);else if(kind==='demoBrute')e=generated(type,40,200,3,10);else if(kind==='demoTravel')e=generated(type,40,200,2,10);else {e=generated(type,40,250,2,10);const base=Date.now()-12*60000;for(let i=0;i<36;i++)e.push({timestamp:new Date(base+i*12000).toISOString(),username:`target${i+1}@demo.test`,source_ip:'203.0.113.88',result:'failure',country:'',user_agent:'VPN Client',device:'Unknown',label:'password_spray'});}S.events=e.sort((a,b)=>Date.parse(a.timestamp)-Date.parse(b.timestamp));S.raw=S.events.map(x=>({...x}));S.columns=Object.keys(S.raw[0]);S.map=guessMap(S.raw);S.source='synthetic';S.datasetName=`synthetic-${type}.json`;S.page='Overview';S.status='Complete';S.incidents=runDetection(S.events);S.selected=null;render();toast(`${type.replace('_',' ')} labelled demo loaded · ${S.incidents.length} incidents detected`);}
function analyze(){if(!S.events.length){toast('Load a dataset first.');return;}S.page='Analyze Logs';renderPage();const els=[...document.querySelectorAll('[data-step]')],bar=document.querySelector('#progress'),msg=document.querySelector('#analysisMessage');let n=0;const tick=()=>{if(n<els.length){els[n].classList.add('done');if(n+1<els.length)els[n+1].classList.add('active');bar.style.width=`${(n+1)/els.length*100}%`;msg.textContent=steps[n]+'…';n++;setTimeout(tick,95);}else{S.incidents=runDetection(S.events);S.status='Complete';S.selected=null;msg.textContent=`Complete · ${S.events.length} events analyzed · ${S.incidents.length} incidents found.`;toast(`${S.incidents.length} incidents detected.`);setTimeout(()=>{if(S.page==='Analyze Logs'){S.page='Incidents';renderPage();}},800);}};tick();}
function download(name,data,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function action(k,id){if(k==='loadDemo'){loadDemo();return;}if(k==='analyze'){analyze();return;}if(k==='generate'){const type=document.querySelector('#scenario').value;const n=+document.querySelector('#usersN').value,e=+document.querySelector('#eventsN').value,int=+document.querySelector('#intensity').value,d=+document.querySelector('#duration').value;S.events=generated(type,n,e,int,d);S.raw=S.events.map(x=>({...x}));S.columns=Object.keys(S.raw[0]||{});S.map=guessMap(S.raw);S.source='synthetic';S.datasetName=`synthetic-${type}.json`;S.incidents=[];S.status='Idle';renderPage();toast(`${S.events.length} events generated · ${S.events.filter(x=>x.label!=='normal').length} attack events.`);return;}if(k.startsWith('demo')){loadSynthetic(k);return;}if(k==='backIncidents'){S.selected=null;S.page='Incidents';renderPage();return;}const inc=S.incidents.find(x=>x.id===id);if(k==='investigated'){if(inc)inc.status='Investigated';toast('Incident marked investigated.');renderPage();}if(k==='evidence'&&inc){download(`${inc.id}-evidence.csv`,'timestamp,username,source_ip,result,country,device\n'+inc.events.map(e=>[e.timestamp,e.username,e.source_ip,e.result,e.country,e.device].map(x=>`"${String(x||'').replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv');}if(k==='kql'&&inc){const ips=inc.events.map(e=>`"${e.source_ip}"`).join(',');showModal('Generated KQL',`SigninLogs\n| where IPAddress in (${ips})\n| where TimeGenerated between (datetime(${inc.first_seen}) .. datetime(${inc.last_seen}))\n| project TimeGenerated, UserPrincipalName, IPAddress, ResultType, Location\n| order by TimeGenerated asc`);}if(k==='sendAlert'&&inc)showModal('Alert preview',`Local alert preview for ${inc.id}\n${inc.type} · ${inc.severity} · risk ${inc.risk}/100\nSource ${inc.source_ip}\nAffected users: ${inc.users.join(', ')}\n\nNo external alert service is configured.`);if(k==='mitre'&&inc)showModal(`${inc.mitre} · ${inc.type}`,`${inc.type==='Brute Force'?'Brute Force: Password Guessing (T1110.001)':inc.type==='Password Spray'?'Brute Force: Password Spraying (T1110.003)':'Valid Accounts (T1078)'}\n\nWhy it applies: ${inc.reason}\nEvidence: ${inc.attempts} associated events from ${inc.source_ip}\nDetected incident: ${inc.id}`);if(k==='exportCSV')download('sprayscope-events.csv','timestamp,username,source_ip,result,country,label\n'+S.events.map(e=>[e.timestamp,e.username,e.source_ip,e.result,e.country,e.label||''].map(x=>`"${String(x).replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv');if(k==='exportJSON')download('sprayscope-report.json',JSON.stringify({dataset:S.datasetName,source:S.source,events:S.events,incidents:S.incidents},null,2),'application/json');if(k==='exportReport')download('sprayscope-report.txt',`SprayScope Report\nDataset: ${S.datasetName}\nSource: ${S.source}\nEvents: ${S.events.length}\nIncidents: ${S.incidents.length}\nHigh/Critical: ${S.incidents.filter(x=>x.risk>=70).length}\nPrecision/Recall: ${S.events.some(e=>e.label)?(()=>{let m=calculateConfusionMatrix(S.events,S.incidents);return `${(m.precision*100).toFixed(1)}% / ${(m.recall*100).toFixed(1)}%`;})():'Not available — dataset is unlabeled.'}\n\n${S.incidents.map(i=>`${i.id} ${i.type} ${i.severity} risk ${i.risk} ${i.mitre}\n${i.reason}`).join('\n\n')}`,'text/plain');if(k==='zoomIn'){S.zoom=Math.min(2.4,S.zoom+.2);renderPage();}if(k==='zoomOut'){S.zoom=Math.max(.55,S.zoom-.2);renderPage();}if(k==='resetZoom'){S.zoom=1;S.pan={x:0,y:0};renderPage();}}
function showModal(title,body){const m=document.createElement('div');m.className='modal-back';m.innerHTML=`<div class="modal"><div class="row"><h2>${esc(title)}</h2><button class="btn ghost sm" data-close>Close</button></div><pre style="white-space:pre-wrap;font:11px/1.7 'DM Mono';color:#bccbe0">${esc(body)}</pre></div>`;document.body.append(m);m.onclick=e=>{if(e.target===m||e.target.closest('[data-close]'))m.remove();};}
document.addEventListener('click',e=>{const button=e.target.closest('[data-fixture]');if(button)loadFixture(button.dataset.fixture);});
function beginReplay(incident){if(!incident)return toast('Run detection before replaying an attack.');if(window.__sprayReplayTimer)clearInterval(window.__sprayReplayTimer);S.replay={type:incident.type,events:[...incident.events].sort((a,b)=>Date.parse(a.timestamp)-Date.parse(b.timestamp)),index:0};S.selected=null;S.entity=null;S.page='Activity Timeline';renderPage();window.__sprayReplayTimer=setInterval(()=>{if(!S.replay)return clearInterval(window.__sprayReplayTimer);if(S.replay.index>=S.replay.events.length-1){clearInterval(window.__sprayReplayTimer);return;}S.replay.index++;if(S.page==='Activity Timeline')renderPage();},750);}
function analystAction(k,id,button){if(k==='portalBrute'||k==='portalSpray'||k==='portalTravel'){runPortalScenario(k);return true;}if(k==='replay'){beginReplay(S.incidents.find(x=>x.id===id));return true;}if(k==='replayLatest'){beginReplay([...S.incidents].sort((a,b)=>b.risk-a.risk)[0]);return true;}if(k==='stopReplay'){clearInterval(window.__sprayReplayTimer);S.replay=null;renderPage();return true;}if(k==='focusGraph'){S.graphIncidentId=id;S.selected=null;S.entity=null;S.page='Attack Graph';renderPage();return true;}if(k==='focusIpGraph'){const ip=button.dataset.value;S.graphIncidentId=S.incidents.find(x=>x.source_ip===ip||x.events.some(e=>e.source_ip===ip))?.id||null;S.entity=null;S.page='Attack Graph';renderPage();return true;}if(k==='backOverview'){S.entity=null;S.selected=null;S.page='Overview';renderPage();return true;}return false;}
document.addEventListener('click',e=>{const navButton=e.target.closest('[data-page]');if(navButton){e.preventDefault();e.stopImmediatePropagation();S.page=navButton.dataset.page;S.entity=null;S.selected=null;document.querySelectorAll('.nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===S.page));renderPage();return;}const entity=e.target.closest('[data-entity]');if(entity){e.preventDefault();e.stopImmediatePropagation();const kind=entity.dataset.entity,value=entity.dataset.value;if(kind==='user'||kind==='ip'){S.entity={kind,value};S.selected=null;renderPage();}else showModal(`${kind.toUpperCase()} details`,`${value}\n\nRelated VPN login events in the loaded dataset are shown in the Attack Source Graph.`);return;}const actionButton=e.target.closest('[data-action]');if(actionButton&&analystAction(actionButton.dataset.action,actionButton.dataset.id,actionButton)){e.preventDefault();e.stopImmediatePropagation();}},true);
document.addEventListener('click',e=>{const pair=e.target.closest('[data-portal-pair]');if(pair){e.preventDefault();e.stopImmediatePropagation();recordPortalComparison();}},true);
let analystSearchTimer;
document.addEventListener('input',e=>{if(e.target.id!=='search')return;e.stopImmediatePropagation();S.search=e.target.value;const caret=e.target.selectionStart;clearTimeout(analystSearchTimer);analystSearchTimer=setTimeout(()=>{renderPage();const next=document.querySelector('#search');if(next){next.focus();next.setSelectionRange(caret,caret);}},140);},true);
document.addEventListener('change',e=>{const filter=e.target.closest('[data-activity-filter]');if(filter){S.activityFilter[filter.dataset.activityFilter]=filter.dataset.activityFilter==='minRisk'?Number(filter.value):filter.value;renderPage();return;}if(e.target.id==='graphSelect'){e.stopImmediatePropagation();S.graphIncidentId=e.target.value;S.selected=null;renderPage();}},true);
document.addEventListener('submit',e=>{if(e.target.id!=='vpnPortalForm')return;e.preventDefault();e.stopImmediatePropagation();submitPortalLogin(e.target);},true);
window.addEventListener('storage',e=>{if(e.key!=='sprayscope-portal-events'||!S.logged)return;let incoming=[];try{incoming=JSON.parse(e.newValue||'[]');}catch{return;}const have=new Set(S.events.map(x=>x.portal_event_id).filter(Boolean));const fresh=incoming.filter(x=>!have.has(x.portal_event_id));if(!fresh.length)return;S.events.push(...fresh);S.events=S.events.slice(-1000).map(x=>({...x,label:null}));S.source='demo';S.isMock=S.isMock||S.datasetName.includes('analyst demo');S.datasetName='VPN analyst demo + user portal attempts';S.incidents=runDetection(S.events);S.status='Complete';if(S.page==='Overview'&&!S.selected&&!S.entity)renderPage();});
async function logoutApp(){localStorage.removeItem('sprayscope-auth');localStorage.removeItem('sprayscope-email-auth');S.logged=false;if(microsoftClient?.getAllAccounts().length){await microsoftClient.logoutRedirect({postLogoutRedirectUri:`${location.origin}/`});return;}login();}
document.addEventListener('click',e=>{if(e.target.closest('#logout')){e.preventDefault();e.stopImmediatePropagation();logoutApp().catch(err=>toast(`Sign-out failed: ${err.message}`));}},true);
async function boot(){if(publicPortal){renderStandalonePortal();return;}if(MICROSOFT_CLIENT_ID){try{await loadMsal();microsoftClient=new window.msal.PublicClientApplication({auth:{clientId:MICROSOFT_CLIENT_ID,authority:MICROSOFT_AUTHORITY,redirectUri:`${location.origin}/`},cache:{cacheLocation:'sessionStorage'}});const response=await microsoftClient.handleRedirectPromise();const account=response?.account||microsoftClient.getAllAccounts()[0];if(account){S.logged=true;S.userName=account.name||account.username||'Analyst';localStorage.setItem('sprayscope-auth','1');}}catch(e){console.error('Microsoft sign-in initialization failed',e);toast('Microsoft sign-in could not be completed. Check app registration and redirect URI.');}}if(S.logged)render();else login();}
boot();

